// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A zero-value Limiter is invalid; use New.
type Limiter struct {
	mu        sync.Mutex
	capacity  float64
	rate      float64 // tokens per second
	tokens    float64
	lastRefill time.Time
	clock     Clock
}

var (
	ErrNonPositiveCapacity = errors.New("ratelimit: capacity must be > 0")
	ErrNonPositiveRate     = errors.New("ratelimit: rate must be > 0")
	ErrNilClock            = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter with the given burst capacity (tokens) and
// refill rate (tokens per second). If clock is nil, the real clock is used.
func New(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrNonPositiveCapacity
	}
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if clock == nil {
		clock = realClock{}
	}
	now := clock.Now()
	return &Limiter{
		capacity:   float64(capacity),
		rate:       rate,
		tokens:     float64(capacity),
		lastRefill: now,
		clock:      clock,
	}, nil
}

// AllowN reports whether n tokens may be consumed at time now.
// It consumes the tokens if allowed.
func (l *Limiter) AllowN(n int) bool {
	return l.allowAtN(l.clock.Now(), n)
}

// Allow reports whether one token may be consumed.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

func (l *Limiter) allowAtN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	elapsed := now.Sub(l.lastRefill).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.lastRefill = now
	}
	if float64(n) > l.tokens {
		return false
	}
	l.tokens -= float64(n)
	return true
}

// Tokens returns the current number of available tokens (for diagnostics).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
